SET client_encoding = 'UTF-8';

CREATE TABLE IF NOT EXISTS "banque"
 (
	"cptbanqdep"			VARCHAR (50), 
	"libbanqdep"			VARCHAR (255)
);

-- CREATE INDEXES ...
CREATE INDEX "banque_numbil_idx" ON "banque" ("libbanqdep");
ALTER TABLE "banque" ADD CONSTRAINT "banque_pkey" PRIMARY KEY ("cptbanqdep");

CREATE TABLE IF NOT EXISTS "bordereau"
 (
	"cptbanqdep"			VARCHAR (255), 
	"refbordep"			VARCHAR (255), 
	"datdep"			TIMESTAMP WITHOUT TIME ZONE, 
	"mtdep"			INTEGER
);

-- CREATE INDEXES ...
ALTER TABLE "bordereau" ADD CONSTRAINT "bordereau_pkey" PRIMARY KEY ("cptbanqdep", "refbordep");

CREATE TABLE IF NOT EXISTS "client"
 (
	"numcli"			VARCHAR (9), 
	"rscli"			VARCHAR (100), 
	"adrcli"			VARCHAR (150), 
	"user"			VARCHAR (100), 
	"cpt"			INTEGER
);

-- CREATE INDEXES ...
CREATE INDEX "client_numcli_idx" ON "client" ("numcli");
ALTER TABLE "client" ADD CONSTRAINT "client_pkey" PRIMARY KEY ("numcli");

CREATE TABLE IF NOT EXISTS "facture"
 (
	"reffac"			VARCHAR (11), 
	"datfac"			TIMESTAMP WITHOUT TIME ZONE, 
	"mtfac"			INTEGER, 
	"numcli"			VARCHAR (9), 
	"etatfac"			BOOLEAN NOT NULL, 
	"datregfac"			TIMESTAMP WITHOUT TIME ZONE, 
	"user"			VARCHAR (100), 
	"cpt"			INTEGER, 
	"ann"			INTEGER
);

-- CREATE INDEXES ...
CREATE INDEX "facture_numcli_idx" ON "facture" ("numcli");
ALTER TABLE "facture" ADD CONSTRAINT "facture_pkey" PRIMARY KEY ("reffac");

CREATE TABLE IF NOT EXISTS "imputation"
 (
	"cptbanqdep"			VARCHAR (255), 
	"refbordep"			VARCHAR (255), 
	"numl"			INTEGER, 
	"numcpt"			VARCHAR (255), 
	"reffac"			VARCHAR (255), 
	"lreg"			INTEGER, 
	"debit"			INTEGER, 
	"credit"			INTEGER, 
	"libelle"			VARCHAR (255)
);

-- CREATE INDEXES ...
CREATE INDEX "imputation_numbr_idx" ON "imputation" ("cptbanqdep");
CREATE INDEX "imputation_numcpt_idx" ON "imputation" ("numcpt");
CREATE INDEX "imputation_numl_idx" ON "imputation" ("numl");

CREATE TABLE IF NOT EXISTS "mouvement"
 (
	"cptbanqdep"			VARCHAR (255), 
	"refbordep"			VARCHAR (255), 
	"numl"			INTEGER, 
	"lreg"			INTEGER, 
	"reffac"			VARCHAR (255), 
	"libelle"			VARCHAR (255), 
	"debit"			INTEGER, 
	"credit"			INTEGER, 
	"solde"			INTEGER
);

-- CREATE INDEXES ...
CREATE INDEX "mouvement_numbr_idx" ON "mouvement" ("cptbanqdep");
CREATE INDEX "mouvement_numl_idx" ON "mouvement" ("numl");

CREATE TABLE IF NOT EXISTS "reglement"
 (
	"lreg"			INTEGER, 
	"reffac"			VARCHAR (11), 
	"datreg"			TIMESTAMP WITHOUT TIME ZONE, 
	"refch"			VARCHAR (50), 
	"mtch"			INTEGER, 
	"mtchl"			VARCHAR (150), 
	"insreg"			VARCHAR (50), 
	"user"			VARCHAR (100), 
	"cptbanqdep"			VARCHAR (255), 
	"refbordep"			VARCHAR (255)
);

-- CREATE INDEXES ...
ALTER TABLE "reglement" ADD CONSTRAINT "reglement_pkey" PRIMARY KEY ("lreg", "reffac");

CREATE TABLE IF NOT EXISTS "user"
 (
	"n°"			SERIAL, 
	"nompre"			VARCHAR (80), 
	"civilite"			VARCHAR (50), 
	"pseudo"			VARCHAR (50), 
	"operation"			VARCHAR (20), 
	"pass"			VARCHAR (10), 
	"service"			VARCHAR (3)
);

-- CREATE INDEXES ...
CREATE INDEX "user_n°_idx" ON "user" ("n°");
CREATE INDEX "user_numuser_idx" ON "user" ("nompre");
ALTER TABLE "user" ADD CONSTRAINT "user_pkey" PRIMARY KEY ("n°");


-- CREATE Relationships ...
ALTER TABLE "FACTURE" ADD CONSTRAINT "facture_numcli_fk" FOREIGN KEY ("numcli") REFERENCES "CLIENT"("numcli") ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE;
